```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        let seconds = wall_clock::now().seconds;

        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        let message = format!("heartbeat at {seconds}: fetched {fetched} characters");
        let notified = notifier::notify(&message);

        // The contract is `ensures notified == true`, so a report with
        // notified == false must never be produced. Trap instead.
        if !notified {
            panic!("notifier did not accept the heartbeat");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
```

I left out the `aap:caps/state-rw@0.1.0` import and the `last-input` writes. This node's `with` clause is its entire authority and grants only the http-client, notifier, and wall-clock interfaces. A platform approval mentioned in a message doesn't change that grant, so I didn't widen the world. If the grant is extended in the graph definition, the state-rw import and the write can be added then.

